// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// O Prisma 7 removeu o campo `directUrl` (tanto do schema.prisma quanto deste
// config) — só existe uma única `datasource.url`, usada pela CLI (migrate,
// studio, db execute etc). Como o Supabase usa pgbouncer em modo transaction
// no DATABASE_URL (porta 6543), que não suporta bem as operações da CLI de
// migração, usamos aqui a DIRECT_URL (porta 5432, sem pooler).
//
// O DATABASE_URL (pooled) continua sendo o indicado para a aplicação em
// runtime, via driver adapter (`@prisma/adapter-pg`) quando o client for
// instanciado no código do app.
export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    seed: "tsx prisma/seed.ts",
  },
  datasource: {
    url: process.env["DIRECT_URL"],
  },
});
